"""Build a self-contained offline HTML deck from the common slide data."""
from pathlib import Path
import json,io,html
import numpy as np
from run import plt
R=Path(__file__).resolve().parents[1];slides=json.loads((R/'presentation/slides.json').read_text());out=[]
for i,d in enumerate(slides):
 content=''
 if d['chart']:
  ch=d['chart'];fig,ax=plt.subplots(figsize=(12,3.8),layout='constrained')
  for j,se in enumerate(ch['series']):
   if ch['kind']=='bar':
    width=.75/len(ch['series']);ax.bar(np.arange(len(se['y']))+(j-(len(ch['series'])-1)/2)*width,se['y'],width=width,color=se['color'],label=se['name'])
   else:ax.plot(se['x'],se['y'],color=se['color'],label=se['name'],lw=1.2 if i==12 else 2.5)
  if ch['kind']=='bar':ax.set_xticks(range(len(ch['categories'])),ch['categories'])
  ax.set(xlabel=ch['xlabel'],ylabel=ch['ylabel']);ax.grid(alpha=.3);ax.set_axisbelow(True);ax.legend(fontsize=10,loc='best');buf=io.StringIO();fig.savefig(buf,format='svg',bbox_inches='tight');plt.close(fig);svg=buf.getvalue();content='<div class="chart">'+svg[svg.index('<svg'):]+ '</div>'
 body=''.join('<p>'+html.escape(b)+'</p>' for b in d['body']);note=html.escape(d['notes'])
 cls='chartslide' if d['chart'] else ('cover' if i==0 else ('refs' if i==17 else 'textslide'))
 out.append(f'<section class="slide {cls}" id="s{i+1}"><header><h1>{html.escape(d["title"])}</h1><div class="sub">{html.escape(d["subtitle"])}</div></header>{content}<div class="body">{body}</div><footer><span>CONTINUOUS WATER SENSING · SIMULATION</span><span>{i+1} / {len(slides)}</span></footer><aside class="notes">{note}</aside></section>')
css='''*{box-sizing:border-box}html,body{margin:0;background:#0b1520;color:#e8edf2;font-family:Arial,Helvetica,sans-serif;height:100%;overflow:hidden}.stage{position:fixed;inset:0;display:flex;align-items:center;justify-content:center}.deck{position:relative;width:1280px;height:720px;flex-shrink:0;transform-origin:center}.slide{display:none;position:absolute;inset:0;padding:44px 64px;background:#0b1520}.slide.active{display:block}h1{font-size:36px;line-height:1.15;letter-spacing:-.6px;margin:0 0 20px;font-weight:750}.sub{font-size:21px;line-height:1.4;color:#a5b7c7}.chart{height:356px;margin:18px 0 10px}.chart svg{width:100%;height:100%}.body p{font-size:25px;line-height:1.42;margin:0 0 27px}.textslide .body{margin-top:34px}.chartslide .body p{font-size:18px;line-height:1.4;margin:0 0 8px}.chartslide .body p:first-child{color:#2dd4bf;font-weight:600}.cover h1{font-size:48px}.cover .body{margin-top:64px}.cover .body p{margin-bottom:36px;font-size:27px}.cover .body p:nth-child(-n+2){color:#2dd4bf;font-weight:700}.refs .body{margin-top:32px}.refs .body p{font-size:20px;line-height:1.35;margin-bottom:20px}footer{position:absolute;bottom:26px;left:64px;right:64px;display:flex;justify-content:space-between;color:#a5b7c7;font-size:12px;letter-spacing:.4px}.controls{position:fixed;bottom:5px;left:50%;transform:translateX(-50%);z-index:10;display:flex;gap:8px;opacity:.3}.controls:hover,.controls:focus-within{opacity:1}button{background:#162436;color:#e8edf2;border:1px solid #456070;padding:5px 10px;border-radius:4px;cursor:pointer}.notes{display:none;position:absolute;left:64px;right:64px;bottom:65px;padding:24px;background:#172e43;border:1px solid #38bdf8;color:white;font-size:19px;line-height:1.5;z-index:5}.show-notes .active .notes{display:block}@media print{@page{size:1280px 720px;margin:0}html,body{height:auto;overflow:visible;print-color-adjust:exact;-webkit-print-color-adjust:exact}.stage{display:block;position:static}.deck{transform:none!important;width:1280px;height:auto}.slide{position:relative;display:block!important;height:720px;break-after:page;page-break-after:always}.slide:last-child{break-after:auto}.controls,.notes{display:none!important}}'''
js='''const slides=[...document.querySelectorAll('.slide')];let pos=Math.max(0,Math.min(slides.length-1,parseInt(location.hash.slice(1)||'1')-1));function show(n){pos=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.classList.toggle('active',i===pos));history.replaceState(null,'','#'+(pos+1));}function scale(){document.querySelector('.deck').style.transform=`scale(${Math.min(innerWidth/1280,innerHeight/720)})`;}function notes(){document.body.classList.toggle('show-notes')}function full(){if(!document.fullscreenElement)document.documentElement.requestFullscreen();else document.exitFullscreen();}addEventListener('resize',scale);addEventListener('keydown',e=>{if(['ArrowRight',' ','PageDown'].includes(e.key)){e.preventDefault();show(pos+1)}else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(pos-1)}else if(e.key==='Home')show(0);else if(e.key==='End')show(slides.length-1);else if(e.key.toLowerCase()==='n')notes();else if(e.key.toLowerCase()==='f')full()});show(pos);scale();'''
page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Continuous Water Sensing — NYUAD Hackathon</title><style>'+css+'</style><div class="stage"><main class="deck">'+''.join(out)+'</main></div><nav class="controls" aria-label="Slide controls"><button onclick="show(pos-1)" aria-label="Previous slide">←</button><button onclick="show(pos+1)" aria-label="Next slide">→</button><button onclick="notes()">Notes (N)</button><button onclick="full()">Fullscreen (F)</button></nav><script>'+js+'</script></html>'
(R/'presentation/Presentation.html').write_text(page);print('Wrote offline HTML with',len(slides),'slides')
